class TinyLiveboardCard extends HTMLElement {
  setConfig(config){
    const height=Number(config.height??480);
    if(!Number.isFinite(height)||height<240||height>2400)throw new Error("Tiny LiveBoard: height must be 240–2400 px");
    this.config={height,profile:typeof config.profile==="string"?config.profile:""};
    if(!this.board){
      this.board=document.createElement("tiny-liveboard");
      const card=document.createElement("ha-card");
      card.style.cssText="overflow:hidden;position:relative";
      card.append(this.board);
      this.append(card);
    }
    this.board.profileOverride=this.config.profile;this.board.style.height=height+"px";if(this.board.ready&&this.board.baseConfig)this.board.applyConfig(this.board.setBaseConfig(this.board.baseConfig));
    if(this._hass)this.board.hass=this._hass;
  }
  set hass(h){this._hass=h;if(this.board)this.board.hass=h}
  getCardSize(){return Math.ceil((this.config?.height||480)/50)}
  static getStubConfig(){return {height:480}}
}
if(!customElements.get("tiny-liveboard-card"))customElements.define("tiny-liveboard-card",TinyLiveboardCard);
